// Capture guide templates (silhouette and target box per body type, exterior slot and lens mode), generated by
// tools/templates and shipped in the app so capture works offline (design 6.2).
import { TEMPLATES } from '../templates/templates.generated';
import type { ExteriorSlot } from './slots';
import type { BodyType } from './vehicle';

// Normalized to the 4:3 photo frame: 0..1 from the left and top edges.
export type Box = { x0: number; y0: number; x1: number; y1: number };

export type CaptureMode = 'normal' | 'wide';

export type Template = {
  bodyType: BodyType;
  slot: ExteriorSlot;
  mode: CaptureMode;
  hfovDeg: number;
  box: Box;
  path: string | null; // SVG path in a 1600×1200 view box; null for the generic frame
};

// Ultra-wide front and rear views put the camera 0.9 m from the bumper (M0), so they stay in normal mode.
export const wideAllowed = (slot: ExteriorSlot): boolean => slot !== 'front' && slot !== 'rear';

const toBox = ([x0, y0, x1, y1]: readonly number[]): Box => ({ x0, y0, x1, y1 });

export function templateFor(bodyType: BodyType, slot: ExteriorSlot, mode: CaptureMode): Template | null {
  if (mode === 'wide' && !wideAllowed(slot)) return null;
  const matches = TEMPLATES.filter((t) => t.slot === slot && t.mode === mode);
  const own = matches.find((t) => t.bodyType === bodyType);
  if (own) return { bodyType, slot, mode, hfovDeg: own.hfovDeg, box: toBox(own.box), path: own.path };
  if (matches.length === 0) return null;
  // Other body types get a generic frame: the mean box of the body types we have, without a silhouette.
  const mean = (i: number) => matches.reduce((sum, t) => sum + t.box[i], 0) / matches.length;
  return { bodyType, slot, mode, hfovDeg: matches[0].hfovDeg, box: toBox([0, 1, 2, 3].map(mean)), path: null };
}
